CREATE TABLE IF NOT EXISTS `Club` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `city` TEXT NOT NULL, `contactInfo` TEXT);
CREATE TABLE IF NOT EXISTS `Coach` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `surname` TEXT NOT NULL, `name` TEXT NOT NULL, `patronymic` TEXT, `phone` TEXT, `clubId` INTEGER NOT NULL, FOREIGN KEY(`clubId`) REFERENCES `Club`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS `index_Coach_clubId` ON `Coach` (`clubId`);
CREATE TABLE IF NOT EXISTS `Fighter` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `surname` TEXT NOT NULL, `name` TEXT NOT NULL, `patronymic` TEXT, `birthDate` TEXT NOT NULL, `weightCategory` TEXT NOT NULL, `clubId` INTEGER NOT NULL, `coachId` INTEGER NOT NULL, FOREIGN KEY(`clubId`) REFERENCES `Club`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT, FOREIGN KEY(`coachId`) REFERENCES `Coach`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS `index_Fighter_clubId` ON `Fighter` (`clubId`);
CREATE INDEX IF NOT EXISTS `index_Fighter_coachId` ON `Fighter` (`coachId`);
CREATE TABLE IF NOT EXISTS `Tournament` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `date` TEXT NOT NULL, `location` TEXT, `organizer` TEXT);
CREATE TABLE IF NOT EXISTS `Fight` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `tournamentId` INTEGER NOT NULL, `date` TEXT NOT NULL, `weightCategory` TEXT NOT NULL, `fighter1Id` INTEGER, `fighter2Id` INTEGER, FOREIGN KEY(`tournamentId`) REFERENCES `Tournament`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`fighter1Id`) REFERENCES `Fighter`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`fighter2Id`) REFERENCES `Fighter`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE INDEX IF NOT EXISTS `index_Fight_tournamentId` ON `Fight` (`tournamentId`);
CREATE INDEX IF NOT EXISTS `index_Fight_fighter1Id` ON `Fight` (`fighter1Id`);
CREATE INDEX IF NOT EXISTS `index_Fight_fighter2Id` ON `Fight` (`fighter2Id`);
CREATE TABLE IF NOT EXISTS `Result` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `fightId` INTEGER NOT NULL, `fighterId` INTEGER NOT NULL, `victoryMethod` TEXT NOT NULL, `round` INTEGER NOT NULL, FOREIGN KEY(`fightId`) REFERENCES `Fight`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE, FOREIGN KEY(`fighterId`) REFERENCES `Fighter`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS `index_Result_fightId` ON `Result` (`fightId`);
CREATE INDEX IF NOT EXISTS `index_Result_fighterId` ON `Result` (`fighterId`);
CREATE TABLE IF NOT EXISTS `AuditLog` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `tableName` TEXT NOT NULL, `operation` TEXT NOT NULL, `recordId` INTEGER NOT NULL, `details` TEXT NOT NULL, `createdAt` TEXT NOT NULL);
